static void pred_to_axi(hls::stream<ap_int8_c>&   inPred,
                        hls::stream<axi_fixed_t>& outAxi)
{
#pragma HLS INLINE
    axi_fixed_t word;
    word.data = 0;
    word.keep = 0;
    word.strb = 0;
    word.last = 1;

    ap_int8_c p = inPred.read();
    word.data.range(7, 0) = p.range(7, 0);

    word.keep = 0x0F;
    word.strb = 0x0F;

    outAxi.write(word);
}

