template<int POOL_SIZE, int STRIDE, int CH, int IN_LEN>
class MaxPool1D_SD {
public:
    void forward(hls::stream<ap_int8_c>& in,
                 hls::stream<ap_int8_c>& out) {

        const int OUT_LEN = (IN_LEN - POOL_SIZE) / STRIDE + 1;

        // Buffer to store one channel's worth of data
        ap_int8_c buffer[IN_LEN];
        #pragma HLS ARRAY_PARTITION variable=buffer complete

        CH_LOOP:
        for (int c = 0; c < CH; ++c) {

            // First, read all input data for this channel into buffer
            READ_CHANNEL:
            for (int i = 0; i < IN_LEN; ++i) {
                #pragma HLS PIPELINE II=1
                buffer[i] = in.read();
            }

            // Now perform pooling from the buffer
            POOL_LOOP:
            for (int out_pos = 0; out_pos < OUT_LEN; ++out_pos) {
                #pragma HLS PIPELINE II=1

                // Calculate window start position
                int window_start = out_pos * STRIDE;

                // Find maximum in the pooling window
                ap_int8_c max_val = buffer[window_start];

                WINDOW_LOOP:
                for (int w = 1; w < POOL_SIZE; ++w) {
                    ap_int8_c val = buffer[window_start + w];
                    if (val > max_val) {
                        max_val = val;
                    }
                }

                out.write(max_val);
            }
        }
    }
};

// -----------------------------------------------------------------------------
// Per-tensor QuantIdentity: spikes {0,1} -> int8 {0, q_one}, q_one = round(1/s)
// act_scale_next_q is s encoded in Q(FRAC_BITS) (per-tensor, zp = 0).
// -----------------------------------------------------------------------------
template<int OUT_CH, int FEATURE_LEN, int FRAC_BITS = 12>
class QuantIdentityPerTensor_Int8 {
public:
    QuantIdentityPerTensor_Int8() {}

    // Forward: in_spk -> out_q (II=1, channel-major C then L)
    void forward(hls::stream<ap_int<8>>& in_spk,     // {0,1}
                 hls::stream<ap_int<8>>& out_q,      // {0, q_one}
                 const ap_int<16> act_scale_next_q)  // Q(FRAC_BITS), s_next > 0
    {
    #pragma HLS INLINE off
        const ap_int<32> ONE_Q = ap_int<32>(1) << FRAC_BITS; // 1.0 in Q
        ap_int<16> q_one_tmp;

        // q_one = round((1<<F)/s) = (ONE_Q + s/2)/s for s>0
        if (act_scale_next_q > 0) {
            q_one_tmp = (ap_int<16>)((ONE_Q + (act_scale_next_q >> 1)) / act_scale_next_q);
        } else {
            q_one_tmp = 127;  // fallback (should not happen)
        }

        // Saturate to int8
        ap_int<8> q_one;
        if (q_one_tmp > 127)         q_one = 127;
        else if (q_one_tmp < -128)   q_one = -128;
        else                         q_one = (ap_int<8>)q_one_tmp;

        for (int c = 0; c < OUT_CH; ++c) {
            for (int t = 0; t < FEATURE_LEN; ++t) {
            #pragma HLS PIPELINE II=1
                ap_int<8> s = in_spk.read(); // 0 or 1
                ap_int<8> q = 0;
                if (s != 0) q = q_one;       // 1 -> q_one
                out_q.write(q);
            }
        }
    }
};

// Quantize signal samples (0-179) using trunk input scale
static inline ap_int8_c quantize_input_sample(float x_real) {
    // x_q = round(x_real / scale) + zero_point, then clamp to int8
    const float inv_s = 1.0f / qcsnet24_cblk1_input_scale;
    float qf = std::nearbyintf(x_real * inv_s) + static_cast<float>(qcsnet24_cblk1_input_zero_point);
    int qi = static_cast<int>(qf);
    if (qi > 127)  qi = 127;
    if (qi < -128) qi = -128;
    return ap_int8_c(qi);
}

